def resolve(path, cwd, links):
    # Normalize input path: prepend cwd if not absolute
    if not path.startswith('/'):
        if not cwd.endswith('/'):
            path = cwd + '/' + path
        else:
            path = cwd + path

    # Split path into components and filter
    components = path.split('/')

    # Start resolution from root
    current = '/'
    links_followed = 0

    for component in components:
        # Skip empty components and '.'
        if component == '' or component == '.':
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent directory
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            # If current is '/', stay at '/'
            continue

        # Append component to current path
        if current == '/':
            candidate = '/' + component
        else:
            candidate = current + '/' + component

        # Check if candidate is a symlink
        if candidate in links:
            links_followed += 1
            if links_followed > 8:
                return None

            # Get the target
            target = links[candidate]

            # Resolve the target
            resolved_target = resolve(target, candidate.rsplit('/', 1)[0] if candidate != '/' + candidate.split('/', 1)[-1] else '/', links)

            if resolved_target is None:
                return None

            current = resolved_target
        else:
            current = candidate

    # Remove trailing slash (except for '/')
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

